// Block Blast service worker.
//
// The pre-cache list further down is generated by `vite.config.js` right after
// `vite build`, so the installed app contains every hashed asset (JS, CSS,
// fonts, icons) and can launch with no network at all. The runtime cache keeps
// later requests fresh while the pre-cached files act as the offline fallback.
const CACHE_PREFIX = 'block-blast'

// BEGIN GENERATED PRECACHE
const BUILD_ID = 'dev'
const PRECACHE_FILES = [
  'index.html',
  'manifest.webmanifest',
  'favicon.svg',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/maskable-512.png',
  'icons/apple-touch-icon.png',
]
// END GENERATED PRECACHE

const SHELL_CACHE = `${CACHE_PREFIX}-shell-${BUILD_ID}`
const RUNTIME_CACHE = `${CACHE_PREFIX}-runtime-${BUILD_ID}`

const scopeUrl = new URL(self.registration.scope)
const shellUrl = new URL('index.html', scopeUrl).href
const precacheUrls = PRECACHE_FILES.map((file) => new URL(file, scopeUrl).href)

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL_CACHE)
      // `reload` bypasses the HTTP cache, so a fresh deploy never mixes a stale
      // index.html with newly hashed asset names in the offline cache.
      await cache.addAll(
        precacheUrls.map((url) => new Request(url, { cache: 'reload' })),
      )
      await self.skipWaiting()
    })(),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys()
      await Promise.all(
        keys
          .filter(
            (key) =>
              key.startsWith(CACHE_PREFIX) &&
              key !== SHELL_CACHE &&
              key !== RUNTIME_CACHE,
          )
          .map((key) => caches.delete(key)),
      )
      await self.clients.claim()
    })(),
  )
})

// Navigation: try the network first so a redeploy is picked up, then fall back
// to the pre-cached shell when the player is offline.
async function handleNavigation(request) {
  try {
    const response = await fetch(request)
    if (response.ok) {
      const shell = await caches.open(SHELL_CACHE)
      await shell.put(shellUrl, response.clone())
      return response
    }
  } catch {
    // Offline or unreachable: use the cached shell below.
  }

  return (
    (await caches.match(request)) ??
    (await caches.match(shellUrl)) ??
    Response.error()
  )
}

// Assets: answer from cache instantly (pre-cache first) while refreshing in the
// background, so the first offline launch always has the full bundle.
async function handleAsset(event, request) {
  const cached = await caches.match(request)
  const runtime = await caches.open(RUNTIME_CACHE)
  const network = fetch(request).then((response) => {
    if (response.ok && response.type === 'basic') {
      runtime.put(request, response.clone())
    }
    return response
  })

  if (cached) {
    event.waitUntil(network.catch(() => {}))
    return cached
  }

  try {
    return await network
  } catch {
    return Response.error()
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET') return

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return

  event.respondWith(
    request.mode === 'navigate' ? handleNavigation(request) : handleAsset(event, request),
  )
})
